const splitKanaForWordSpell = (kana) =>
  Array.from(kana).reduce((chunks, char) => {
    if (["ゃ", "ゅ", "ょ", "ャ", "ュ", "ョ"].includes(char) && chunks.length > 0) {
      chunks[chunks.length - 1] += char;
    } else {
      chunks.push(char);
    }
    return chunks;
  }, []);

