const n5VocabGrowthChainQuestions = n5VocabGrowthWordGroups.flatMap((group) => {
  const meaningOptions = group.words.map(([, , , meaning]) => meaning);
  return group.words.flatMap(([knowledgeId, kana, romaji, meaning]) => {
    const chunks = splitKanaForWordSpell(kana);
    return [
      {
        id: `q-n5-vocab-growth-${knowledgeId.replace("word-n5-", "")}-meaning`,
        levelId: group.levelId,
        questionType: "word-to-meaning",
        knowledgeIds: [knowledgeId],
        questionText: "看假名，选中文意思。",
        prompt: kana,
        audioKey: `word.${romaji}`,
        audioSrc: `assets/audio/words/${romaji}.wav`,
        options: meaningOptions,
        correctAnswer: meaning,
        difficulty: 5,
        isPreview: false,
        noRomaji: true,
      },
      {
        id: `q-n5-vocab-growth-${knowledgeId.replace("word-n5-", "")}-spell`,
        levelId: group.levelId,
        questionType: "word-spell",
        knowledgeIds: [knowledgeId],
        questionText: "看中文意思，按顺序点假名块拼出词。",
        prompt: meaning,
        chunks,
        audioKey: `word.${romaji}`,
        audioSrc: `assets/audio/words/${romaji}.wav`,
        options: [...chunks],
        correctAnswer: chunks.join("|"),
        difficulty: 5,
        isPreview: false,
        noRomaji: true,
      },
    ];
  });
});

const n5ScenarioQuestions = n5ScenarioQuestionGroups.flatMap((group) => {
  const wordOptions = group.words.map(([, kana]) => kana);
  const meaningOptions = group.sentences.map(([, , chinese]) => chinese);
  const wordQuestions = group.words.flatMap(([knowledgeId, kana, romaji]) => [
    {
      id: `q-${group.wordLevelId.replace("level-", "")}-${romaji}-audio`,
      levelId: group.wordLevelId,
      questionType: "audio-to-word",
      knowledgeIds: [knowledgeId],
      questionText: "听声音，选词语。",
      audioKey: `word.${romaji}`,
      audioSrc: `assets/audio/words/${romaji}.wav`,
      options: wordOptions,
      correctAnswer: kana,
      difficulty: 4,
      isPreview: false,
      noRomaji: true,
    },
    {
      id: `q-${group.wordLevelId.replace("level-", "")}-${romaji}-image`,
      levelId: group.wordLevelId,
      questionType: "image-to-word",
      knowledgeIds: [knowledgeId],
      questionText: "看图，选出这个词。",
      options: n5ImageOptionMap[romaji] || wordOptions,
      correctAnswer: kana,
      difficulty: 4,
      isPreview: false,
      noRomaji: true,
    },
  ]);
  const sentenceQuestions = group.sentences.flatMap(([knowledgeId, prompt, chinese], index) => {
    const sentenceAudio = `assets/audio/sentences/${knowledgeId.replace("sentence-", "")}.wav`;
    const base = [
      {
        id: `q-${group.sentenceLevelId.replace("level-", "")}-${knowledgeId.replace("sentence-n5-", "")}-meaning`,
        levelId: group.sentenceLevelId,
        questionType: "sentence-to-meaning",
        knowledgeIds: [knowledgeId],
        questionText: "看句子，选意思。",
        prompt,
        audioKey: `sentence.${knowledgeId.replace("sentence-", "")}`,
        audioSrc: sentenceAudio,
        options: meaningOptions,
        correctAnswer: chinese,
        difficulty: 4,
        isPreview: false,
        noRomaji: true,
      },
    ];
    if (index < 2) {
      base.unshift({
        id: `q-${group.sentenceLevelId.replace("level-", "")}-${knowledgeId.replace("sentence-n5-", "")}-audio`,
        levelId: group.sentenceLevelId,
        questionType: "audio-to-sentence-meaning",
        knowledgeIds: [knowledgeId],
        questionText: "听句子，选意思。",
        audioKey: `sentence.${knowledgeId.replace("sentence-", "")}`,
        audioSrc: sentenceAudio,
        options: meaningOptions,
        correctAnswer: chinese,
        difficulty: 4,
        isPreview: false,
        noRomaji: true,
      });
    }
    return base;
  });
  const [speechKnowledgeId, speechPrompt, speechMeaning] = group.sentences[0];
  const speechQuestions = [
    buildTopicSpeechSentenceQuestion({
      id: `q-${group.sentenceLevelId.replace("level-", "")}-${speechKnowledgeId.replace("sentence-n5-", "")}-speak`,
      levelId: group.sentenceLevelId,
      knowledgeId: speechKnowledgeId,
      prompt: speechPrompt,
      meaning: speechMeaning,
      difficulty: 5,
    }),
  ];
  const fillQuestions = group.fills.map(([id, knowledgeId, prompt, options, correctAnswer]) => ({
    id,
    levelId: group.sentenceLevelId,
    questionType: "sentence-fill",
    knowledgeIds: [knowledgeId],
    questionText: "把词放进空格。",
    prompt,
    audioKey: `sentence.${knowledgeId.replace("sentence-", "")}`,
    audioSrc: `assets/audio/sentences/${knowledgeId.replace("sentence-", "")}.wav`,
    options,
    correctAnswer,
    difficulty: 4,
    isPreview: false,
    noRomaji: true,
  }));
  const orderSource = group.sentences.find(([, prompt]) => prompt.replace("。", "").split(/\s+/).length >= 2) || group.sentences[0];
  const orderQuestions = orderSource
    ? (() => {
        const [knowledgeId, prompt, chinese] = orderSource;
        const chunks = prompt.replace("。", "").split(/\s+/).filter(Boolean);
        if (chunks.length < 2 || new Set(chunks).size !== chunks.length) return [];
        return [
          {
            id: `q-${group.sentenceLevelId.replace("level-", "")}-${knowledgeId.replace("sentence-n5-", "")}-order`,
            levelId: group.sentenceLevelId,
            questionType: "sentence-order",
            knowledgeIds: [knowledgeId],
            questionText: "按顺序点词块，组成短句。",
            prompt: chinese,
            chunks,
            audioKey: `sentence.${knowledgeId.replace("sentence-", "")}`,
            audioSrc: `assets/audio/sentences/${knowledgeId.replace("sentence-", "")}.wav`,
            options: chunks,
            correctAnswer: chunks.join("|"),
            difficulty: 5,
            isPreview: false,
            noRomaji: true,
          },
        ];
      })()
    : [];
  return [...wordQuestions, ...sentenceQuestions, ...speechQuestions, ...fillQuestions, ...orderQuestions];
});

function getUniqueSentenceChunks(sentence) {
  const chunks = String(sentence || "").replace("。", "").split(/\s+/).filter(Boolean);
  if (chunks.length < 2 || new Set(chunks).size !== chunks.length) return [];
  return chunks;
}

function getSentenceAudioSrc(knowledgeId) {
  return `assets/audio/sentences/${knowledgeId.replace("sentence-", "")}.wav`;
}

function normalizeSpeechAnswer(value) {
  return String(value || "").replace(/[\s、。！？?！,.，・]/g, "");
}

function buildTopicSpeechSentenceQuestion({ id, levelId, knowledgeId, prompt, meaning, audioKey = null, audioSrc = null, difficulty = 6 }) {
  const normalizedAnswer = normalizeSpeechAnswer(prompt);
  return {
    id,
    levelId,
    questionType: "speech-sentence",
    knowledgeIds: [knowledgeId],
    questionText: "听范例，再说一句。",
    speechTarget: prompt,
    speechHint: meaning,
    prompt,
    audioKey: audioKey || `sentence.${knowledgeId.replace("sentence-", "")}`,
    audioSrc: audioSrc || getSentenceAudioSrc(knowledgeId),
    correctAnswer: normalizedAnswer,
    acceptedAnswers: [normalizedAnswer],
    minDurationMs: 1200,
    difficulty,
    isPreview: false,
    noRomaji: true,
  };
}

const n5ScenarioBuilderQuestions = n5ScenarioQuestionGroups.flatMap((group) => {
  const levelId = getN5ScenarioBuilderLevelId(group.wordLevelId);
  const builderKey = levelId.replace(/^level-/, "");
  const scenarioOptions = group.sentences.slice(0, 4).map(([, sentence]) => sentence);
  const fillQuestions = group.fills.slice(0, 2).map(([originalId, knowledgeId, prompt, options, correctAnswer], index) => ({
    id: `q-${builderKey}-bridge-fill-${index + 1}-${originalId.replace(/^q-n5-/, "")}`,
    levelId,
    questionType: "sentence-fill",
    knowledgeIds: [knowledgeId],
    questionText: "把词放进空格。",
    prompt,
    audioKey: `sentence.${knowledgeId.replace("sentence-", "")}`,
    audioSrc: getSentenceAudioSrc(knowledgeId),
    options,
    correctAnswer,
    difficulty: 5,
    isPreview: false,
    noRomaji: true,
  }));

  const orderQuestions = group.sentences
    .map(([knowledgeId, sentence, chinese]) => {
      const chunks = getUniqueSentenceChunks(sentence);
      if (!chunks.length) return null;
      return {
        id: `q-${builderKey}-bridge-order-${knowledgeId.replace("sentence-n5-", "")}`,
        levelId,
        questionType: "sentence-order",
        knowledgeIds: [knowledgeId],
        questionText: "按顺序点词块，组成短句。",
        prompt: chinese,
        chunks,
        audioKey: `sentence.${knowledgeId.replace("sentence-", "")}`,
        audioSrc: getSentenceAudioSrc(knowledgeId),
        options: chunks,
        correctAnswer: chunks.join("|"),
        difficulty: 5,
        isPreview: false,
        noRomaji: true,
      };
    })
    .filter(Boolean)
    .slice(0, 2);

  const scenarioQuestions = group.sentences.slice(0, 2).map(([knowledgeId, sentence, chinese], index) => ({
    id: `q-${builderKey}-bridge-scenario-${index + 1}-${knowledgeId.replace("sentence-n5-", "")}`,
    levelId,
    questionType: "sentence-scenario",
    knowledgeIds: [knowledgeId],
    questionText: "看场景，选一句。",
    prompt: `你想表达“${chinese.replace(/。$/, "")}”。`,
    options: scenarioOptions.includes(sentence) ? scenarioOptions : [sentence, ...scenarioOptions].slice(0, 4),
    correctAnswer: sentence,
    difficulty: 5,
    isPreview: false,
    noRomaji: true,
  }));

  return [...fillQuestions, ...orderQuestions, ...scenarioQuestions];
});

