const n5ReviewQuestions = n5ReviewQuestionGroups.flatMap((group) => {
  const wordOptions = group.words.map(([, kana]) => kana);
  const meaningOptions = group.sentences.map(([, , chinese]) => chinese);
  const wordQuestions = group.words.flatMap(([knowledgeId, kana, romaji]) => [
    {
      id: `q-${group.levelId.replace("level-", "")}-${romaji}-audio`,
      levelId: group.levelId,
      questionType: "audio-to-word",
      knowledgeIds: [knowledgeId],
      questionText: "听声音，选词语。",
      audioKey: `word.${romaji}`,
      audioSrc: `assets/audio/words/${romaji}.wav`,
      options: wordOptions,
      correctAnswer: kana,
      difficulty: 5,
      isPreview: false,
      noRomaji: true,
    },
    {
      id: `q-${group.levelId.replace("level-", "")}-${romaji}-image`,
      levelId: group.levelId,
      questionType: "image-to-word",
      knowledgeIds: [knowledgeId],
      questionText: "看图，选出这个词。",
      options: n5ImageOptionMap[romaji] || wordOptions,
      correctAnswer: kana,
      difficulty: 5,
      isPreview: false,
      noRomaji: true,
    },
  ]);
  const sentenceQuestions = group.sentences.flatMap(([knowledgeId, prompt, chinese], index) => {
    const sentenceAudio = `assets/audio/sentences/${knowledgeId.replace("sentence-", "")}.wav`;
    const base = [
      {
        id: `q-${group.levelId.replace("level-", "")}-${knowledgeId.replace("sentence-n5-", "")}-meaning`,
        levelId: group.levelId,
        questionType: "sentence-to-meaning",
        knowledgeIds: [knowledgeId],
        questionText: "看句子，选意思。",
        prompt,
        audioKey: `sentence.${knowledgeId.replace("sentence-", "")}`,
        audioSrc: sentenceAudio,
        options: meaningOptions,
        correctAnswer: chinese,
        difficulty: 5,
        isPreview: false,
        noRomaji: true,
      },
    ];
    if (index < 2) {
      base.unshift({
        id: `q-${group.levelId.replace("level-", "")}-${knowledgeId.replace("sentence-n5-", "")}-audio`,
        levelId: group.levelId,
        questionType: "audio-to-sentence-meaning",
        knowledgeIds: [knowledgeId],
        questionText: "听句子，选意思。",
        audioKey: `sentence.${knowledgeId.replace("sentence-", "")}`,
        audioSrc: sentenceAudio,
        options: meaningOptions,
        correctAnswer: chinese,
        difficulty: 5,
        isPreview: false,
        noRomaji: true,
      });
    }
    return base;
  });
  const fillQuestions = group.fills.map(([id, knowledgeId, prompt, options, correctAnswer]) => ({
    id,
    levelId: group.levelId,
    questionType: "sentence-fill",
    knowledgeIds: [knowledgeId],
    questionText: "把词放进空格。",
    prompt,
    audioKey: `sentence.${knowledgeId.replace("sentence-", "")}`,
    audioSrc: `assets/audio/sentences/${knowledgeId.replace("sentence-", "")}.wav`,
    options,
    correctAnswer,
    difficulty: 5,
    isPreview: false,
    noRomaji: true,
  }));
  const [orderId, orderKnowledgeId, orderPrompt, orderChunks] = group.order;
  const orderQuestion = {
    id: orderId,
    levelId: group.levelId,
    questionType: "sentence-order",
    knowledgeIds: [orderKnowledgeId],
    questionText: "按顺序点词块，组成短句。",
    prompt: orderPrompt,
    chunks: orderChunks,
    audioKey: `sentence.${orderKnowledgeId.replace("sentence-", "")}`,
    audioSrc: `assets/audio/sentences/${orderKnowledgeId.replace("sentence-", "")}.wav`,
    options: orderChunks,
    correctAnswer: orderChunks.join("|"),
    difficulty: 5,
    isPreview: false,
    noRomaji: true,
  };
  const [scenarioId, scenarioKnowledgeId, scenarioPrompt, scenarioOptions, scenarioCorrectAnswer] = group.scenario;
  const scenarioQuestion = {
    id: scenarioId,
    levelId: group.levelId,
    questionType: "sentence-scenario",
    knowledgeIds: [scenarioKnowledgeId],
    questionText: "看场景，选一句自然日语。",
    prompt: scenarioPrompt,
    audioKey: `sentence.${scenarioKnowledgeId.replace("sentence-", "")}`,
    audioSrc: `assets/audio/sentences/${scenarioKnowledgeId.replace("sentence-", "")}.wav`,
    options: scenarioOptions,
    correctAnswer: scenarioCorrectAnswer,
    difficulty: 5,
    isPreview: false,
    noRomaji: true,
  };
  return [...wordQuestions, ...sentenceQuestions, ...fillQuestions, orderQuestion, scenarioQuestion];
});

