const n5VisualLoopWords = n5VocabGrowthWordGroups.flatMap((group) => {
  const groupWordOptions = group.words.map(([, kana]) => kana);
  const groupMeaningOptions = group.words.map(([, , , meaning]) => meaning);
  return group.words.map(([knowledgeId, kana, romaji, meaning]) => ({
    romaji,
    kana,
    knowledgeId,
    audioKey: `word.${romaji}`,
    audioSrc: `assets/audio/words/${romaji}.wav`,
    meaning,
    meaningOptions: groupMeaningOptions,
    options: n5ImageOptionMap[romaji] || groupWordOptions,
  }));
});

const n5VisualLoopQuestionTypes = ["audio-to-image", "word-to-image", "image-to-meaning"];
const n5VisualLoopQuestionSuffixes = {
  "audio-to-image": "audio-image",
  "word-to-image": "word-image",
  "image-to-meaning": "image-meaning",
};

const n5VisualLoopQuestions = n5VisualLoopWords.map((word, index) => {
  const questionType = n5VisualLoopQuestionTypes[index % n5VisualLoopQuestionTypes.length];
  const baseQuestion = {
    id: `q-n5-visual-loop-${word.romaji}-${n5VisualLoopQuestionSuffixes[questionType]}`,
    levelId: "level-n5-visual-loop-practice",
    questionType,
    knowledgeIds: [word.knowledgeId],
    questionText: questionType === "image-to-meaning" ? "看图片，选意思。" : questionType === "word-to-image" ? "看词语，选图片。" : "听声音，选图片。",
    difficulty: 5,
    isPreview: false,
    noRomaji: true,
  };
  if (questionType === "image-to-meaning") {
    return {
      ...baseQuestion,
      options: word.meaningOptions,
      correctAnswer: word.meaning,
    };
  }
  return {
    ...baseQuestion,
    prompt: questionType === "word-to-image" ? word.kana : undefined,
    audioKey: word.audioKey,
    audioSrc: word.audioSrc,
    options: word.options,
    correctAnswer: word.kana,
  };
});

