const basicSingleKanaRomajiSet = new Set(basicSingleKanaRomaji);
const basicHandwritingKanaIds = new Set(basicSingleKanaRomaji.flatMap((romaji) => [`kana-hira-${romaji}`, `kana-kata-${romaji}`]));

function expectedBasicHandwritingLevelId(knowledgeId) {
  const match = /^kana-(hira|kata)-(.+)$/.exec(knowledgeId || "");
  if (!match) return "";
  const [, script, romaji] = match;
  if (!basicSingleKanaRomajiSet.has(romaji)) return "";
  if (vowelLearningLevelByRomaji[romaji]) {
    return script === "hira" ? `level-${vowelLearningLevelByRomaji[romaji]}` : `level-kata-${vowelLearningLevelByRomaji[romaji]}`;
  }
  return `level-${script}-${romaji}`;
}

