function rotateQuestionOptions(options) {
  if (!Array.isArray(options) || options.length <= 1) return options || [];
  return [...options.slice(1), options[0]];
}

function buildFourSkillWordQuestions(levelId, prefix, targets) {
  const kanaOptions = targets.map((target) => target.kana);
  const meaningOptions = targets.map((target) => target.meaning);
  return targets.flatMap((target) => [
    {
      id: `q-${prefix}-listen-word-${target.slug}`,
      levelId,
      questionType: "audio-to-word",
      knowledgeIds: [target.knowledgeId],
      questionText: "听声音，选词语。",
      audioKey: target.audioKey,
      audioSrc: target.audioSrc,
      options: rotateQuestionOptions(kanaOptions),
      correctAnswer: target.kana,
      difficulty: 5,
      isPreview: false,
      noRomaji: true,
    },
    {
      id: `q-${prefix}-speak-word-${target.slug}`,
      levelId,
      questionType: "speech-word",
      knowledgeIds: [target.knowledgeId],
      questionText: "听范例，再读这个词。",
      speechTarget: target.kana,
      speechHint: target.meaning,
      prompt: target.kana,
      audioKey: target.audioKey,
      audioSrc: target.audioSrc,
      correctAnswer: target.kana,
      acceptedAnswers: target.acceptedAnswers,
      minDurationMs: 700,
      difficulty: 5,
      isPreview: false,
      noRomaji: true,
    },
    {
      id: `q-${prefix}-read-word-${target.slug}`,
      levelId,
      questionType: "word-to-meaning",
      knowledgeIds: [target.knowledgeId],
      questionText: "看词语，选意思。",
      prompt: target.kana,
      audioKey: target.audioKey,
      audioSrc: target.audioSrc,
      options: rotateQuestionOptions(meaningOptions),
      correctAnswer: target.meaning,
      difficulty: 5,
      isPreview: false,
      noRomaji: true,
    },
    {
      id: `q-${prefix}-write-word-${target.slug}`,
      levelId,
      questionType: "word-spell",
      knowledgeIds: [target.knowledgeId],
      questionText: "看中文意思，按顺序点假名块拼出词。",
      prompt: target.meaning,
      chunks: target.chunks,
      audioKey: target.audioKey,
      audioSrc: target.audioSrc,
      options: rotateQuestionOptions(target.chunks),
      correctAnswer: target.chunks.join("|"),
      difficulty: 5,
      isPreview: false,
      noRomaji: true,
    },
  ]);
}

function buildFourSkillSentenceQuestions(levelId, prefix, targets) {
  const meaningOptions = targets.map((target) => target.meaning);
  return targets.flatMap((target) => [
    {
      id: `q-${prefix}-listen-sentence-${target.slug}`,
      levelId,
      questionType: "audio-to-sentence-meaning",
      knowledgeIds: [target.knowledgeId],
      questionText: "听句子，选意思。",
      audioKey: target.audioKey,
      audioSrc: target.audioSrc,
      options: rotateQuestionOptions(meaningOptions),
      correctAnswer: target.meaning,
      difficulty: 6,
      isPreview: false,
      noRomaji: true,
    },
    {
      id: `q-${prefix}-speak-sentence-${target.slug}`,
      levelId,
      questionType: "speech-sentence",
      knowledgeIds: [target.knowledgeId],
      questionText: "听范例，再读这句话。",
      speechTarget: target.prompt,
      speechHint: target.meaning,
      prompt: target.prompt,
      audioKey: target.audioKey,
      audioSrc: target.audioSrc,
      correctAnswer: target.normalizedAnswer,
      acceptedAnswers: [target.normalizedAnswer],
      minDurationMs: 1400,
      difficulty: 6,
      isPreview: false,
      noRomaji: true,
    },
    {
      id: `q-${prefix}-read-sentence-${target.slug}`,
      levelId,
      questionType: "sentence-to-meaning",
      knowledgeIds: [target.knowledgeId],
      questionText: "看句子，选意思。",
      prompt: target.prompt,
      audioKey: target.audioKey,
      audioSrc: target.audioSrc,
      options: rotateQuestionOptions(meaningOptions),
      correctAnswer: target.meaning,
      difficulty: 6,
      isPreview: false,
      noRomaji: true,
    },
    {
      id: `q-${prefix}-write-sentence-${target.slug}`,
      levelId,
      questionType: "sentence-order",
      knowledgeIds: [target.knowledgeId],
      questionText: "按顺序点词块，组成自然短句。",
      prompt: target.meaning,
      chunks: target.chunks,
      audioKey: target.audioKey,
      audioSrc: target.audioSrc,
      options: rotateQuestionOptions(target.chunks),
      correctAnswer: target.chunks.join("|"),
      difficulty: 6,
      isPreview: false,
      noRomaji: true,
    },
  ]);
}

